<script setup lang="ts">
import {computed,ref,reactive,watch,nextTick,toRaw} from 'vue';
import type {Component,Database,Port,PortKind,Slot,Specs} from '../shared/types';
import {categories,portKinds} from '../shared/types';
import {componentCapabilities,storageAdapterKind,storageAdapterKinds} from '../shared/component-capabilities';
import {componentFields,componentSections,fieldSection,type ComponentSection} from '../shared/component-fields';
import {componentSchema,componentSpecsSchema} from '../shared/component-schema';
import {nextComponentId,portIdPrefix,supportsSlotBifurcation,issueSection,componentReferences,type ComponentCollection} from '../shared/component-editor';
import {catalogSuggestions,normalizeCatalogValue,normalizeCatalogValues,catalogNumericValuesRule} from '../shared/catalog-options';
import ComponentSpecFields from './ComponentSpecFields.vue';
import ComponentRecordList from './ComponentRecordList.vue';
const props=defineProps<{component:Component;db:Database}>();
const root=ref<HTMLElement|null>(null),section=ref<ComponentSection>('basics'),errors=ref<string[]>([]),jsonMode=ref(false),jsonText=ref(''),jsonOriginal=ref('');
const capability=computed(()=>componentCapabilities(props.component)),sections=computed(()=>componentSections(props.component));
const labels:Record<ComponentSection,string>={basics:'Basics',ports:'Ports',expansion:'Expansion',storage:'Storage',physical:'Physical',review:'Review'};
const selected=reactive<Record<ComponentCollection,number>>({ports:0,slots:0,laneRules:0,bayTargets:0,driveTargets:0,sataDataPorts:0,sataPowerConnectors:0,sataDataInputs:0,sataPowerInputs:0});
const electricalPanel=ref<string|undefined>(),lanePanel=ref<string|undefined>();
const portKind=ref<PortKind>('Ethernet'),portCount=ref(1),slotBus=ref<'PCI'|'PCIe'>('PCIe'),physicalList=ref<'bayTargets'|'driveTargets'>('bayTargets'),storageList=ref<ComponentCollection>('sataDataPorts');
const automaticIds=new WeakMap<object,string>();
const fields=computed(()=>componentFields(props.component).filter(field=>fieldSection(field.key,props.component)===section.value));
const specs=computed(()=>props.component.specs);
watch(()=>JSON.stringify(props.component),()=>errors.value=[],{flush:'sync'});
const retainedFields=computed(()=>{const keys=new Set<string>(componentFields(props.component).map(field=>field.key));keys.add('notes');if(props.component.category==='Storage adapter')keys.add('storageAdapterKind');if(props.component.category==='Drive')keys.add('driveKind');if(capability.value.ports)keys.add('ports');if(props.component.category==='Motherboard'){keys.add('slots');keys.add('laneRules');}if(capability.value.pci){keys.add('pciVoltage');keys.add('pciBits');}if(capability.value.nvmeSled)keys.add('bifurcationMode');if(capability.value.software)for(const key of ['supportedOS','requiredDriver','requiredFirmware'])keys.add(key);if(capability.value.controller){keys.add('bootable');keys.add('hotPlug');}if(capability.value.bayProvider)keys.add('bayTargets');if(capability.value.bayConsumer)for(const key of ['baySize','bayUnits','lengthMm'])keys.add(key);if(capability.value.driveTargets)keys.add('driveTargets');for(const option of storageOptions.value){keys.add(option.value);const count=endpointCountKey(option.value);if(count)keys.add(count);}return Object.keys(specs.value).filter(key=>!keys.has(key));});
const port=computed(()=>specs.value.ports?.[selected.ports]),slot=computed(()=>specs.value.slots?.[selected.slots]),rule=computed(()=>specs.value.laneRules?.[selected.laneRules]);
const bay=computed(()=>specs.value.bayTargets?.[selected.bayTargets]),target=computed(()=>specs.value.driveTargets?.[selected.driveTargets]);
function rows(key:ComponentCollection){return (specs.value[key]||[]) as {id:string}[];}
function references(key:ComponentCollection,row?:{id:string}){return row?componentReferences(props.component,key,row.id,props.db):[];}
function listItems(key:ComponentCollection){return rows(key).map((row,index)=>({id:row.id,summary:key==='ports'?`${specs.value.ports![index].kind} · ${specs.value.ports![index].connector||'Connector unknown'}`:key==='slots'?`${specs.value.slots![index].bus} · position ${specs.value.slots![index].position}`:key==='bayTargets'?`${specs.value.bayTargets![index].size} inch · ${specs.value.bayTargets![index].group||'Bank unknown'}`:key==='driveTargets'?`${specs.value.driveTargets![index].mount} · ${specs.value.driveTargets![index].interfaces?.join(', ')||'Interface unknown'}`:'Named physical connector'}));}
const storageOptions=computed(()=>{const options:{title:string;value:ComponentCollection}[]=[];if(capability.value.sataController)options.push({title:'SATA data ports provided',value:'sataDataPorts'});if(props.component.category==='PSU')options.push({title:'SATA power plugs provided',value:'sataPowerConnectors'});if(capability.value.adapter==='bay-cage')options.push({title:'SATA data inputs consumed',value:'sataDataInputs'});if(capability.value.adapter==='bay-cage'||props.component.category==='Bay accessory'||specs.value.sataPowerInputs!==undefined||specs.value.sataPowerPlugs!==undefined)options.push({title:'SATA power inputs consumed',value:'sataPowerInputs'});return options;});
const endpoint=computed(()=>rows(storageList.value)[selected[storageList.value]] as {id:string;harness?:string}|undefined);
const physicalOptions=computed(()=>[{title:'Physical mounting bays',value:'bayTargets' as const},...(capability.value.driveTargets?[{title:'Drive service positions',value:'driveTargets' as const}]:[])].filter(item=>item.value!=='bayTargets'||capability.value.bayProvider));
watch(storageOptions,options=>{if(!options.some(option=>option.value===storageList.value)&&options[0])storageList.value=options[0].value;},{immediate:true});
watch(physicalOptions,options=>{if(!options.some(option=>option.value===physicalList.value)&&options[0])physicalList.value=options[0].value;},{immediate:true});
watch(sections,options=>{if(!options.includes(section.value))section.value='basics';});
const suggestions=(key:string)=>catalogSuggestions(props.db,key);
function optional(object:object,key:string,value:unknown,numeric=false){const row=object as Record<string,unknown>;if(value==null||value==='')delete row[key];else row[key]=numeric?Number(value):value;}
function list(object:object,key:string,value:unknown,numeric=false){const row=object as Record<string,unknown>;try{row[key]=normalizeCatalogValues(value,suggestions(key),{numeric});}catch{row[key]=value;}}
function newId(type:string,key:ComponentCollection){return nextComponentId(type,rows(key));}
function remember(row:{id:string}){automaticIds.set(toRaw(row),row.id);}
function kindChanged(row:Port){if(automaticIds.get(toRaw(row))===row.id){row.id=nextComponentId(portIdPrefix(row.kind,row.customType),rows('ports').filter(port=>port!==row));remember(row);}}
function slotBusChanged(row:Slot){if(automaticIds.get(toRaw(row))===row.id){row.id=nextComponentId(row.bus,rows('slots').filter(slot=>slot!==row));remember(row);}}
function addPorts(){if(!Number.isInteger(portCount.value)||portCount.value<1||portCount.value>100||rows('ports').length+portCount.value>1000){errors.value=['Add between 1 and 100 ports at a time, up to 1,000 total.'];return;}const ports=specs.value.ports??=[];const first=ports.length;for(let i=0;i<portCount.value;i++){const row:Port={id:newId(portIdPrefix(portKind.value),'ports'),kind:portKind.value};remember(row);ports.push(row);}selected.ports=first;}
function addSlot(){const slots=specs.value.slots??=[];if(slots.length>=32){errors.value=['A motherboard supports at most 32 slot records.'];return;}let position=1;while(slots.some(slot=>slot.position===position))position++;const row:Slot={id:newId(slotBus.value,'slots'),bus:slotBus.value,physical:slotBus.value==='PCIe'?16:1,lanes:slotBus.value==='PCIe'?4:1,generation:3,position};remember(row);slots.push(row);selected.slots=slots.length-1;}
function remove(key:ComponentCollection){const row=rows(key)[selected[key]],refs=references(key,row);if(refs.length){errors.value=[`Keep ${row.id}: used by ${refs.join(', ')}. Update those bindings first.`];return;}rows(key).splice(selected[key],1);selected[key]=Math.min(selected[key],rows(key).length-1);syncCounts(key);}
function syncCounts(key:ComponentCollection){if(key==='sataDataPorts')specs.value.sataPorts=rows(key).length;if(key==='sataPowerConnectors')specs.value.sataPower=rows(key).length;if(key==='sataPowerInputs')specs.value.sataPowerPlugs=rows(key).length;}
const endpointPrefixes:Partial<Record<ComponentCollection,string>>={sataDataPorts:'SATA_DATA',sataPowerConnectors:'SATA_POWER',sataDataInputs:'SATA_DATA_IN',sataPowerInputs:'SATA_POWER_IN'};
function addEndpoint(){const key=storageList.value;if(rows(key).length>=1000){errors.value=['A connector list supports at most 1,000 records.'];return;}const values=(specs.value as Record<string,unknown>)[key]??=[];const list=values as {id:string}[];list.push({id:newId(endpointPrefixes[key]||'SATA',key)});selected[key]=list.length-1;syncCounts(key);}
function endpointCountKey(key:ComponentCollection){return key==='sataDataPorts'?'sataPorts':key==='sataPowerConnectors'?'sataPower':key==='sataPowerInputs'?'sataPowerPlugs':undefined;}
function nameFromCount(){const key=storageList.value,countKey=endpointCountKey(key),count=countKey?specs.value[countKey]:undefined;if(count===undefined||!Number.isInteger(count)||count<0||count>1000){errors.value=['Enter a whole connector count from 0 to 1,000.'];return;}if(rows(key).length){errors.value=['This list already has named connectors. Edit the existing records or use count only first.'];return;}(specs.value as Record<string,unknown>)[key]=Array.from({length:count},(_,i)=>({id:`${endpointPrefixes[key]}_${i+1}`}));selected[key]=0;syncCounts(key);}
function countOnly(){const key=storageList.value,used=rows(key).flatMap(row=>references(key,row));if(used.length){errors.value=[`Named connectors are used by ${[...new Set(used)].join(', ')}. Update those bindings first.`];return;}syncCounts(key);delete specs.value[key];selected[key]=0;}
function addRule(){(specs.value.laneRules??=[]).push({id:newId('LANE_RULE','laneRules'),slots:[]});selected.laneRules=rows('laneRules').length-1;}
function addPhysical(){const key=physicalList.value;if(rows(key).length>=1000){errors.value=['A physical list supports at most 1,000 records.'];return;}if(key==='bayTargets')(specs.value.bayTargets??=[]).push({id:newId('BAY_525',key),size:'5.25'});else (specs.value.driveTargets??=[]).push({id:newId(capability.value.nvmeSled?'NVME_TARGET':'DRIVE_TARGET',key),mount:capability.value.adapter==='bay-cage'?'front-hot-swap':capability.value.nvmeSled?'rear-sled':'internal'});selected[key]=rows(key).length-1;}
function keep(items:{title:string;value:string}[],value?:string){return value&&!items.some(item=>item.value===value)?[...items,{title:value+' (recorded; unavailable)',value}]:items;}
function applyExample(kind:string){const keys:ComponentCollection[]=kind==='chassis'?['bayTargets']:['driveTargets','sataDataInputs','sataPowerInputs'];const used=keys.flatMap(key=>rows(key).flatMap(row=>references(key,row)));if(used.length){errors.value=[`Example replacement is blocked by ${[...new Set(used)].join(', ')}.`];return;}if(keys.some(key=>rows(key).length)&&!window.confirm('Replace these catalogs with an unverified example?'))return;if(kind==='chassis'){specs.value.bays525=2;specs.value.bayTargets=[1,2].map(position=>({id:`BAY_525_${position}`,size:'5.25',group:'Front optical bank',position}));}else{const size=kind==='25'?'2.5':'3.5',count=kind==='35-three'?3:2;Object.assign(specs.value,{storageAdapterKind:'bay-cage',baySize:'5.25',bayUnits:size==='2.5'?1:2,sataDataInputs:Array.from({length:count},(_,i)=>({id:`SATA_DATA_IN_${i+1}`})),sataPowerInputs:[{id:'SATA_POWER_IN_1'}],sataPowerPlugs:1,driveTargets:Array.from({length:count},(_,i)=>({id:`DRIVE_TARGET_${i+1}`,mount:'front-hot-swap',driveSizes:[size],interfaces:['SATA'],sataDataInputId:`SATA_DATA_IN_${i+1}`,sataPowerInputId:'SATA_POWER_IN_1'}))});}props.component.verified=false;}
function jsonChanged(){return jsonMode.value&&jsonText.value!==jsonOriginal.value;}
function beginJson(){jsonText.value=JSON.stringify(specs.value,null,2);jsonOriginal.value=jsonText.value;jsonMode.value=true;}
function applyJson(){try{const parsed=JSON.parse(jsonText.value),validation=componentSpecsSchema.safeParse(parsed);if(!validation.success){errors.value=validation.error.issues.map(issue=>`${issue.path.join('.')}: ${issue.message}`);return false;}props.component.specs=parsed;jsonMode.value=false;errors.value=[];return true;}catch{errors.value=['Specifications must be valid JSON.'];return false;}}
function canChangeSection(){if(!jsonMode.value)return true;if(!jsonChanged()){jsonMode.value=false;return true;}return applyJson();}
function changeSection(next:ComponentSection){if(next===section.value)return;if(!canChangeSection())return;section.value=next;void nextTick(()=>root.value?.closest('.v-card-text')?.scrollTo(0,0));}
async function validate(){if(jsonMode.value){if(jsonChanged()&&!applyJson()){section.value='review';return false;}jsonMode.value=false;}const validation=componentSchema.safeParse(props.component);if(!validation.success){errors.value=validation.error.issues.map(issue=>`${issue.path.join('.')}: ${issue.message}`);const issue=validation.error.issues[0],next=issueSection(issue.path,props.component);section.value=sections.value.includes(next)?next:'review';const key=String(issue.path[1]) as ComponentCollection;if(key in selected){if(typeof issue.path[2]==='number')selected[key]=issue.path[2];else{const seen=new Set<string>(),duplicate=rows(key).findIndex(row=>{const value=issue.message.toLowerCase().includes('position')?String((row as {position?:number}).position):row.id;if(seen.has(value))return true;seen.add(value);return false;});if(duplicate>=0)selected[key]=duplicate;}}if(key==='ports'&&['pinout','powerW','isolated'].includes(String(issue.path.at(-1))))electricalPanel.value='electrical';if(key==='laneRules')lanePanel.value='lanes';if(key.startsWith('sata'))storageList.value=key;if(key==='bayTargets'||key==='driveTargets')physicalList.value=key;await nextTick();root.value?.querySelector<HTMLElement>('[data-field="'+String(issue.path.at(-1))+'"] input')?.focus();return false;}const original=props.db.components.find(component=>component.id===props.component.id);if(original)for(const key of Object.keys(selected) as ComponentCollection[])for(const row of (original.specs[key]||[]) as {id:string}[])if(!rows(key).some(next=>next.id===row.id)){const refs=references(key,row);if(refs.length){errors.value=[`Keep ${row.id}: used by ${refs.join(', ')}. Update those bindings first.`];section.value='review';return false;}}errors.value=[];return true;}
function getContext(){return {section:section.value,selected:{...selected},storageList:storageList.value,physicalList:physicalList.value};}
function restoreContext(context:ReturnType<typeof getContext>|undefined,view:string){if(context){for(const key of Object.keys(selected) as ComponentCollection[])if(Number.isInteger(context.selected[key]))selected[key]=Math.max(0,Math.min(context.selected[key],rows(key).length-1));if(storageOptions.value.some(option=>option.value===context.storageList))storageList.value=context.storageList;if(physicalOptions.value.some(option=>option.value===context.physicalList))physicalList.value=context.physicalList;}section.value=sections.value.includes(view as ComponentSection)?view as ComponentSection:'basics';}
defineExpose({validate,hasPendingChanges:jsonChanged,canChangeSection,getContext,restoreContext});
</script>
<template>
 <div ref="root" class="component-data-editor control-stack">
  <v-tabs :model-value="section" aria-label="Component data sections" class="component-section-tabs" show-arrows @update:model-value="v=>changeSection(v as ComponentSection)"><v-tab v-for="item in sections" :key="item" :value="item">{{labels[item]}}</v-tab></v-tabs>
  <v-alert v-if="errors.length" type="error" variant="tonal" role="alert" class="my-4"><strong>Resolve these fields before saving.</strong><ul><li v-for="message in errors" :key="message">{{message}}</li></ul></v-alert>
  <p class="form-hint">Blank means unknown. Enter zero or “Not supported” only when confirmed. All sections are saved together.</p>
  <section class="control-stack" v-if="section==='basics'" aria-label="Component basics"><div class="form-grid"><v-text-field v-model="component.name" label="Component name *" data-field="name" required :rules="[v=>!!String(v||'').trim()||'A name is required.']" /><v-select v-model="component.category" label="Category" :items="categories" /><v-combobox :model-value="component.manufacturer" label="Manufacturer" :items="suggestions('manufacturer')" :return-object="false" clearable @update:model-value="v=>component.manufacturer=normalizeCatalogValue(v,suggestions('manufacturer'))||''" /><v-text-field v-model="component.source" label="Source / manufacturer documentation URL" /><v-select v-if="component.category==='Storage adapter'" :model-value="storageAdapterKind(component)" :items="storageAdapterKinds" label="Storage adapter role" @update:model-value="v=>optional(component.specs,'storageAdapterKind',v)" /><v-select v-if="component.category==='Drive'" :model-value="component.specs.driveKind||(capability.optical?'optical':'disk')" :items="[{title:'Storage disk / SSD',value:'disk'},{title:'Optical drive',value:'optical'}]" label="Drive kind" @update:model-value="v=>optional(component.specs,'driveKind',v)" /></div></section>
  <ComponentSpecFields v-if="fields.length" :component="component" :db="db" :fields="fields" />
  <section class="control-stack" v-if="section==='ports'&&capability.ports">
   <h3>Physical ports</h3><p class="form-hint">Use one record per physical connector. New IDs include the interface type; existing IDs are retained. A complete named catalog replaces USB/Ethernet counts.</p>
   <div class="component-add-toolbar"><v-select v-model="portKind" label="New port type" :items="portKinds" hide-details density="compact" /><v-text-field v-model.number="portCount" label="Number to add" type="number" min="1" max="100" hide-details density="compact" /><v-btn variant="outlined" @click="addPorts">Add ports</v-btn></div>
   <ComponentRecordList v-model="selected.ports" label="Physical ports" :items="listItems('ports')"><template v-if="port"><h3>{{port.id}}</h3><p v-if="references('ports',port).length" class="form-hint">ID retained for {{references('ports',port).join(', ')}}.</p><div class="form-grid mt-3"><v-text-field v-model="port.id" label="Port ID" data-field="id" :readonly="!!references('ports',port).length" /><v-select v-model="port.kind" label="Kind" :items="portKinds" @update:model-value="kindChanged(port)" /><v-text-field v-if="port.kind==='Custom'" v-model="port.customType" label="Custom interface name" data-field="customType" @update:model-value="kindChanged(port)" /><v-text-field v-model="port.connector" label="Connector" /><v-text-field v-model="port.protocol" label="Protocol" /><v-text-field :model-value="port.speedMbps" label="Rated speed (Mbps)" type="number" min="0" data-field="speedMbps" @update:model-value="v=>optional(port!,'speedMbps',v,true)" /></div><v-expansion-panels v-model="electricalPanel" variant="accordion" class="my-3"><v-expansion-panel value="electrical" title="Electrical and pinout details"><v-expansion-panel-text><div class="form-grid"><v-text-field v-model="port.pinout" label="Pinout / wiring standard" data-field="pinout" /><v-text-field :model-value="port.powerW" label="Supplied power (W)" data-field="powerW" type="number" min="0" @update:model-value="v=>optional(port!,'powerW',v,true)" /><v-select :model-value="port.isolated??null" label="Isolated interface" :items="[{title:'Unknown',value:null},{title:'Yes',value:true},{title:'No',value:false}]" @update:model-value="v=>optional(port!,'isolated',v)" /></div></v-expansion-panel-text></v-expansion-panel></v-expansion-panels><v-btn variant="text" color="error" :disabled="!!references('ports',port).length" @click="remove('ports')">Remove port</v-btn></template></ComponentRecordList>
  </section>
  <section class="control-stack" v-if="section==='expansion'">
   <template v-if="component.category==='Motherboard'"><h3>Expansion slots</h3><p class="form-hint">Physical connector width, electrical lanes and rear bracket position are separate. Edit one slot at a time.</p><div class="component-add-toolbar"><v-select v-model="slotBus" label="New slot bus" :items="['PCIe','PCI']" hide-details density="compact" /><v-btn variant="outlined" @click="addSlot">Add slot</v-btn></div><ComponentRecordList v-model="selected.slots" label="Expansion slots" :items="listItems('slots')"><template v-if="slot"><div class="form-grid"><v-text-field v-model="slot.id" label="Slot ID" :readonly="!!references('slots',slot).length" data-field="id" /><v-select v-model="slot.bus" label="Bus" :items="['PCIe','PCI']" @update:model-value="slotBusChanged(slot)" /><v-text-field v-model.number="slot.position" label="Position" type="number" min="1" max="32" data-field="position" /><template v-if="slot.bus==='PCIe'"><v-text-field v-model.number="slot.physical" label="Physical width (x)" type="number" min="1" max="16" data-field="physical" /><v-text-field v-model.number="slot.lanes" label="Electrical lanes" type="number" min="1" max="16" data-field="lanes" /><v-text-field v-model.number="slot.generation" label="PCIe generation" type="number" min="1" max="7" data-field="generation" /><v-combobox v-if="supportsSlotBifurcation(component)" :model-value="slot.bifurcationModes||[]" :items="suggestions('bifurcationModes')" label="Supported bifurcation modes" multiple chips closable-chips clearable :return-object="false" @update:model-value="v=>list(slot!,'bifurcationModes',v)" /></template><template v-else><v-select :model-value="slot.pciVoltage" @update:model-value="v=>optional(slot!,'pciVoltage',v)" label="PCI voltage / keying" :items="['3.3V','5V','universal']" clearable /><v-select :model-value="slot.pciBits" @update:model-value="v=>optional(slot!,'pciBits',v)" label="PCI data width (bits)" :items="[32,64]" clearable /></template></div><p v-if="slot.bus==='PCIe'&&!supportsSlotBifurcation(component)" class="form-hint">Bifurcation is not supported. Saved slot modes are retained but ignored while this declaration is active.</p><p v-if="references('slots',slot).length" class="form-hint">Used by {{references('slots',slot).join(', ')}}.</p><v-btn variant="text" color="error" :disabled="!!references('slots',slot).length" @click="remove('slots')">Remove slot</v-btn></template></ComponentRecordList></template>
   <template v-if="capability.pci"><div class="form-grid"><v-select :model-value="component.specs.pciVoltage" @update:model-value="v=>optional(component.specs,'pciVoltage',v)" label="PCI voltage / keying" :items="['3.3V','5V','universal']" clearable /><v-select :model-value="component.specs.pciBits" @update:model-value="v=>optional(component.specs,'pciBits',v)" label="PCI data width (bits)" :items="[32,64]" clearable /></div></template>
   <v-combobox v-if="capability.nvmeSled" :model-value="component.specs.bifurcationMode" :items="suggestions('bifurcationModes')" label="Required bifurcation mode" clearable :return-object="false" @update:model-value="v=>optional(component.specs,'bifurcationMode',normalizeCatalogValue(v,suggestions('bifurcationModes')))" />
   <v-expansion-panels v-if="capability.laneRules" v-model="lanePanel" variant="accordion" class="my-5"><v-expansion-panel value="lanes" title="Lane sharing and disabled ports"><v-expansion-panel-text><v-btn variant="outlined" class="mb-3" @click="addRule">Add lane rule</v-btn><ComponentRecordList v-model="selected.laneRules" label="Lane rules" :items="listItems('laneRules')"><template v-if="rule"><div class="form-grid"><v-text-field v-model="rule.id" label="Rule ID" data-field="id" /><v-select v-model="rule.slots" label="Participating slots" data-field="slots" :items="component.specs.slots?.map(slot=>slot.id)||[]" multiple chips /><v-text-field :model-value="rule.maxLanes" label="Shared maximum lanes" data-field="maxLanes" type="number" min="0" @update:model-value="v=>optional(rule!,'maxLanes',v,true)" /><v-checkbox v-model="rule.exclusive" label="Mutually exclusive slots" /><v-text-field :model-value="rule.disableM2Slots" label="M.2 slots disabled" data-field="disableM2Slots" type="number" min="0" @update:model-value="v=>optional(rule!,'disableM2Slots',v,true)" /><v-text-field :model-value="rule.disableSataPorts" label="SATA ports disabled" data-field="disableSataPorts" type="number" min="0" @update:model-value="v=>optional(rule!,'disableSataPorts',v,true)" /><v-select v-model="rule.disableSataPortIds" label="Specific SATA ports disabled" data-field="disableSataPortIds" :items="keep((component.specs.sataDataPorts||[]).map(port=>({title:port.id,value:port.id})))" multiple chips /></div><v-btn color="error" variant="text" @click="remove('laneRules')">Remove rule</v-btn></template></ComponentRecordList></v-expansion-panel-text></v-expansion-panel></v-expansion-panels>
  </section>
  <section class="control-stack" v-if="section==='storage'">
   <p class="form-hint">SATA data channels and power plugs are separate resources. Named catalogs describe the complete inventory.</p><template v-if="storageOptions.length"><v-select v-model="storageList" label="Connector catalog" :items="storageOptions" /><v-text-field v-if="storageList==='sataPowerInputs'&&component.specs.sataPowerInputs===undefined" :model-value="component.specs.sataPowerPlugs" label="SATA power inputs required" type="number" min="0" @update:model-value="v=>optional(component.specs,'sataPowerPlugs',v,true)" /><div class="component-add-toolbar"><v-btn variant="outlined" @click="addEndpoint">Add connector</v-btn><v-btn v-if="endpointCountKey(storageList)" variant="text" :disabled="component.specs[endpointCountKey(storageList)!]===undefined||!!rows(storageList).length" @click="nameFromCount">Name connectors from count</v-btn><v-btn v-if="component.specs[storageList]!==undefined&&endpointCountKey(storageList)" variant="text" @click="countOnly">Use count only</v-btn></div><ComponentRecordList v-model="selected[storageList]" :label="storageOptions.find(option=>option.value===storageList)?.title||'SATA connectors'" :items="listItems(storageList)"><template v-if="endpoint"><v-text-field v-model="endpoint.id" label="Connector ID" data-field="id" :readonly="!!references(storageList,endpoint).length" /><v-text-field v-if="storageList==='sataPowerConnectors'" v-model="endpoint.harness" label="PSU harness / cable" /><p v-if="references(storageList,endpoint).length" class="form-hint">Used by {{references(storageList,endpoint).join(', ')}}.</p><v-checkbox v-if="storageList==='sataDataPorts'" v-model="(endpoint as {disabled?:boolean}).disabled" label="Port disabled" /><v-btn color="error" variant="text" :disabled="!!references(storageList,endpoint).length" @click="remove(storageList)">Remove connector</v-btn></template></ComponentRecordList></template>
  </section>
  <section class="control-stack" v-if="section==='physical'">
   <template v-if="capability.bayConsumer"><div class="form-grid"><v-select :model-value="component.specs.baySize" label="Required mounting bay size (inches)" :items="['2.5','3.5','5.25']" clearable @update:model-value="v=>optional(component.specs,'baySize',v)" /><v-text-field :model-value="component.specs.bayUnits" label="Mounting bays consumed per unit (default 1)" type="number" min="1" @update:model-value="v=>optional(component.specs,'bayUnits',v,true)" /><v-text-field :model-value="component.specs.lengthMm" label="Device mounting depth (mm)" type="number" min="0" @update:model-value="v=>optional(component.specs,'lengthMm',v,true)" /></div></template>
   <div v-if="component.category==='Chassis'||capability.adapter==='bay-cage'" class="component-add-toolbar"><v-menu><template #activator="{props:menu}"><v-btn v-bind="menu" variant="text">Unverified examples</v-btn></template><v-list><v-list-item v-if="component.category==='Chassis'" title="Two optical mounting bays" @click="applyExample('chassis')" /><template v-else><v-list-item title="Dual 2.5-inch cage" @click="applyExample('25')" /><v-list-item title="Dual 3.5-inch cage" @click="applyExample('35')" /><v-list-item title="Triple 3.5-inch cage" @click="applyExample('35-three')" /></template></v-list></v-menu></div>
   <template v-if="physicalOptions.length"><v-select v-model="physicalList" label="Physical catalog" :items="physicalOptions" /><v-btn variant="outlined" class="mb-3" @click="addPhysical">Add {{physicalList==='bayTargets'?'mounting bay':'drive position'}}</v-btn><ComponentRecordList v-model="selected[physicalList]" :label="physicalList==='bayTargets'?'Mounting bays':'Drive positions'" :items="listItems(physicalList)"><template v-if="physicalList==='bayTargets'&&bay"><div class="form-grid"><v-text-field v-model="bay.id" label="Mounting bay ID" :readonly="!!references('bayTargets',bay).length" data-field="id" /><v-select v-model="bay.size" label="Mounting bay size (inches)" :items="['2.5','3.5','5.25']" /><v-text-field v-model="bay.group" label="Bay bank / adjacency group" /><v-text-field :model-value="bay.position" label="Position within bank" data-field="position" type="number" min="1" @update:model-value="v=>optional(bay!,'position',v,true)" /><v-text-field :model-value="bay.maxDepthMm" label="Available device depth (mm)" type="number" min="0" @update:model-value="v=>optional(bay!,'maxDepthMm',v,true)" /></div><v-btn color="error" variant="text" :disabled="!!references('bayTargets',bay).length" @click="remove('bayTargets')">Remove mounting bay</v-btn></template><template v-else-if="target"><div class="form-grid"><v-text-field v-model="target.id" label="Target ID" :readonly="!!references('driveTargets',target).length" data-field="id" /><v-select v-model="target.mount" label="Mount / access" :items="['auto','internal','front-hot-swap','rear-sled']" /><v-combobox :model-value="target.driveSizes||[]" :items="suggestions('driveSizes')" label="Supported drive sizes" multiple chips closable-chips clearable :return-object="false" @update:model-value="v=>list(target!,'driveSizes',v)" /><v-combobox :model-value="target.interfaces||[]" :items="suggestions('interfaces')" label="Supported interfaces" multiple chips closable-chips clearable :return-object="false" @update:model-value="v=>list(target!,'interfaces',v)" /><v-combobox :model-value="target.m2Lengths||[]" :items="suggestions('m2Lengths')" :rules="[catalogNumericValuesRule]" label="M.2 lengths (mm)" multiple chips closable-chips clearable :return-object="false" @update:model-value="v=>list(target!,'m2Lengths',v,true)" /><v-select :model-value="target.bayId||''" label="Physical bay alias" data-field="bayId" :items="keep([{title:'No alias',value:''},...(component.specs.bayTargets||[]).map(bay=>({title:bay.id,value:bay.id}))],target.bayId)" @update:model-value="v=>optional(target!,'bayId',v)" /><v-select :model-value="target.hotSwap??null" label="Hot-swappable" :items="[{title:'Unknown',value:null},{title:'Yes',value:true},{title:'No',value:false}]" @update:model-value="v=>optional(target!,'hotSwap',v)" /><v-select :model-value="target.bootable??null" label="Bootable target" :items="[{title:'Unknown',value:null},{title:'Yes',value:true},{title:'No',value:false}]" @update:model-value="v=>optional(target!,'bootable',v)" /></div><div v-if="capability.adapter==='bay-cage'" class="form-grid"><v-select :model-value="target.sataDataInputId||''" label="Tray SATA data input" data-field="sataDataInputId" :items="keep([{title:'Not recorded',value:''},...(component.specs.sataDataInputs||[]).map(input=>({title:input.id,value:input.id}))],target.sataDataInputId)" @update:model-value="v=>optional(target!,'sataDataInputId',v)" /><v-select :model-value="target.sataPowerInputId||''" label="Tray SATA power input" data-field="sataPowerInputId" :items="keep([{title:'Not recorded',value:''},...(component.specs.sataPowerInputs||[]).map(input=>({title:input.id,value:input.id}))],target.sataPowerInputId)" @update:model-value="v=>optional(target!,'sataPowerInputId',v)" /></div><v-btn color="error" variant="text" :disabled="!!references('driveTargets',target).length" @click="remove('driveTargets')">Remove drive position</v-btn></template></ComponentRecordList></template>
  </section>
  <section class="control-stack" v-if="section==='review'"><h3>Review specifications</h3><p>Saved sections: {{sections.filter(item=>item!=='review').map(item=>labels[item]).join(', ')}}.</p><p v-if="retainedFields.length" class="form-hint">Retained fields outside this category: {{retainedFields.join(', ')}}.</p><template v-if="capability.software&&!jsonMode"><div class="form-grid"><v-combobox :model-value="component.specs.supportedOS||[]" :items="suggestions('supportedOS')" label="Supported operating systems" multiple chips closable-chips clearable :return-object="false" @update:model-value="v=>list(component.specs,'supportedOS',v)" /><v-text-field v-model="component.specs.requiredDriver" label="Required driver version" /><v-text-field v-model="component.specs.requiredFirmware" label="Required firmware version" /></div></template><div v-if="capability.controller&&!jsonMode" class="form-grid"><v-select :model-value="component.specs.bootable??null" label="Controller boot support" :items="[{title:'Unknown',value:null},{title:'Yes',value:true},{title:'No',value:false}]" @update:model-value="v=>optional(component.specs,'bootable',v)" /><v-select :model-value="component.specs.hotPlug??null" label="Controller hot-plug support" :items="[{title:'Unknown',value:null},{title:'Yes',value:true},{title:'No',value:false}]" @update:model-value="v=>optional(component.specs,'hotPlug',v)" /></div><v-textarea v-if="!jsonMode" v-model="component.specs.notes" label="Specification notes / restrictions" rows="2" /><v-checkbox v-model="component.verified" label="I have verified these specifications against manufacturer documentation" color="primary" /><v-btn v-if="!jsonMode" variant="text" @click="beginJson">Edit specifications JSON</v-btn><template v-else><p class="form-hint">Applying JSON validates every field. Identifiers used by plans and installations must stay stable.</p><v-textarea v-model="jsonText" label="Specifications JSON" rows="10" class="json-editor" /><div class="component-add-toolbar"><v-btn variant="outlined" @click="applyJson">Apply JSON to form</v-btn><v-btn variant="text" @click="jsonMode=false">Discard JSON edits</v-btn></div></template></section>
 </div>
</template>
