:deep(.component-record-layout){display:grid;grid-template-columns:minmax(180px,240px) minmax(0,1fr);gap:24px}:deep(.component-record-list){min-width:0;align-self:start}:deep(.component-record-detail){min-width:0}:deep(.component-record-list .v-list-item-title),:deep(.component-record-list .v-list-item-subtitle){white-space:normal;overflow-wrap:anywhere}
